package domain

import (
	"crypto/rand"
	"fmt"
	"regexp"
)

// MaxUploadBytes is the largest source file accepted (2GB, see CONTEXT.md).
const MaxUploadBytes int64 = 2 << 30

// NewID returns a random UUID (version 4). IDs are generated by the
// application, not by the database.
func NewID() string {
	var b [16]byte
	rand.Read(b[:]) // never fails since Go 1.24
	b[6] = b[6]&0x0f | 0x40
	b[8] = b[8]&0x3f | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

var idPattern = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)

// IsID reports whether s looks like a UUID, so handlers can answer 404
// instead of sending malformed IDs to PostgreSQL.
func IsID(s string) bool {
	return idPattern.MatchString(s)
}
